// tests/wasm/wasm_test.mjs: the wasm32 build of vbm-json against the Lean reference (run by scripts/test_wasm.sh; test code, not shipped).
// Usage: node wasm_test.mjs VBM.wasm VECTORS.jsonl DUMP.txt     (rows of vbm-json-vectors-1, generated by the Lean REFERENCE)
// Checks: the module imports nothing; every row's verdict and error code; an accepted row's tape read back to the reference's canonical bytes (the 100000-deep rows are DEPTH, no trap); the allocator hook refuses an impossible size; no growth and no live bytes after many parses (the leak check). Writes DUMP.txt = "<id> <rc> <fnv1a64 of the tape>" per row,
// the same lines tests/abi_dump.c writes for the native ABI: scripts/test_wasm.sh diffs the two. Exit 0 = all pass.
import { readFileSync, writeFileSync } from "node:fs";
import { load, tapeToCompact, OK, SYNTAX, DEPTH, ARG } from "./vbm_json.mjs";

const [wasmPath, vecPath, dumpPath] = process.argv.slice(2);
if (!dumpPath) { console.error("usage: wasm_test.mjs VBM.wasm VECTORS.jsonl DUMP.txt"); process.exit(2); }
const wasm = readFileSync(wasmPath);
const imports = WebAssembly.Module.imports(new WebAssembly.Module(wasm));
let failures = 0;
const fail = (m) => { console.error("FAIL: " + m); failures++; };
if (imports.length) fail("the module has imports: " + imports.map((i) => i.module + "." + i.name).join(" "));
const lib = await load(wasm);
const hex = (s) => Uint8Array.from(s.match(/../g) ?? [], (h) => parseInt(h, 16));
const fnv = (words, text) => {
  let h = 14695981039346656037n; const M = (1n << 64n) - 1n;
  for (const b of new Uint8Array(words.buffer, words.byteOffset, words.byteLength)) h = ((h ^ BigInt(b)) * 1099511628211n) & M;
  for (const b of text) h = ((h ^ BigInt(b)) * 1099511628211n) & M;
  return h.toString(16).padStart(16, "0");
};

const lines = readFileSync(vecPath, "utf8").split("\n").filter(Boolean);
const strict = new TextDecoder("utf-8", { fatal: true });   // the WHATWG decoder: strict UTF-8, the independent decider for the escape check
const literal = (b) => { const o = [0x22]; for (const c of b) { if (c === 0x22) o.push(0x5c, 0x22); else if (c === 0x5c) o.push(0x5c, 0x5c); else if (c === 8) o.push(0x5c, 0x62); else if (c === 12) o.push(0x5c, 0x66);
  else if (c === 10) o.push(0x5c, 0x6e); else if (c === 13) o.push(0x5c, 0x72); else if (c === 9) o.push(0x5c, 0x74); else if (c < 0x20) o.push(...Buffer.from("\\u00" + c.toString(16).padStart(2, "0"))); else o.push(c); } o.push(0x22); return Buffer.from(o); };
let nprint = 0, nesc = 0, nescbad = 0;
const dump = []; let ok = 0, syn = 0, dep = 0; let okIn = null, errIn = null;
for (let id = 0; id < lines.length; id++) {
  const row = JSON.parse(lines[id]);
  if (!okIn && row.verdict === "ok" && row.input.length > 80 && row.input.length < 400) okIn = hex(row.input);   // the leak check below parses rows of the generated set, no input of its own
  if (!errIn && row.verdict === "err" && row.code === "syntax" && row.input.length > 4 && row.input.length < 400) errIn = hex(row.input);
  let r; try { r = lib.parse(hex(row.input)); } catch (e) { fail(`row ${id} (set ${row.set}): the module TRAPPED (${e.message}): a trap is never an answer`); continue; }
  dump.push(`${id} ${r.code} ${r.code === OK ? fnv(r.words, r.text) : "0000000000000000"}`);
  if (row.verdict === "ok") {
    if (r.code !== OK) { fail(`row ${id}: the reference accepts, the module answers ${r.code}`); continue; }
    let got; try { got = tapeToCompact(r); } catch (e) { fail(`row ${id}: ${e.message}`); continue; }
    if (Buffer.compare(Buffer.from(got), Buffer.from(hex(row.canonical))) !== 0) fail(`row ${id}: the tape does not read back to the canonical form`); else ok++;
    const p = lib.printed(hex(row.input));   // vbm_json_print_tape in the module: the reference's canonical bytes
    if (p.code !== OK || Buffer.compare(Buffer.from(p.bytes), Buffer.from(hex(row.canonical))) !== 0) fail(`row ${id}: print_tape in the module is not the canonical form (code ${p.code})`); else nprint++;
  } else {
    const want = row.code === "syntax" ? SYNTAX : row.code === "depth" ? DEPTH : -1;
    if (r.code !== want) fail(`row ${id}: the verdict or error code differs from the reference (want ${row.code}, got ${r.code})`);
    else if (r.code === SYNTAX) syn++; else dep++;
  }
}
// escape_string in the module on the input of every row (valid UTF-8 or not: the WHATWG strict decoder decides)
for (let id = 0; id < lines.length; id++) {
  const input = hex(JSON.parse(lines[id]).input); let valid = true; try { strict.decode(input); } catch { valid = false; }
  if (input.length > 20000) continue;
  const e = lib.escaped(input);
  if (valid) { if (e.code !== OK || Buffer.compare(Buffer.from(e.bytes), literal(input)) !== 0) fail(`row ${id}: escape_string in the module differs from the escape table (code ${e.code})`); else nesc++; }
  else if (e.code !== SYNTAX) fail(`row ${id}: escape_string accepts text that is not UTF-8 (code ${e.code})`); else nescbad++;
}
if (lines.length < Number(process.env.VBM_MIN_ROWS || 1000)) fail(`only ${lines.length} rows`);
writeFileSync(dumpPath, dump.join("\n") + "\n");
console.log(`wasm_test: ${lines.length} rows (${ok} accepted and read back to the canonical form, ${syn} syntax errors, ${dep} depth errors); print_tape gives the canonical bytes on ${nprint}; escape_string: ${nesc} texts to the literal, ${nescbad} non-UTF-8 texts refused`);

// the module is still usable after every row (the deep ones included: the generated set has 100000-deep arrays and objects, DEPTH and no trap): the first row again answers as before
{ const again = lib.parse(hex(JSON.parse(lines[0]).input)); if (`0 ${again.code} ${again.code === OK ? fnv(again.words, again.text) : "0000000000000000"}` !== dump[0]) fail("the module answers differently on the first row after all the rows"); }
if (!okIn || !errIn) fail("the vectors lack an accepted row and a syntax-error row to leak-check with");

// the allocator hook: an impossible size is refused (0), a bad length is ARG
if (lib.exports.vbm_json_wasm_alloc(1500000000) !== 0) fail("an impossible allocation was not refused");
if (lib.parse({ length: 0x7fffffff }).code !== ARG) fail("an oversized input is not ARG");
console.log("wasm_test: the allocator refuses an impossible size; an oversized input is ARG");

// leak: the arena returns to its live baseline after every parse, and does not grow over many parses
const doc = okIn;
lib.parse(doc); const live0 = lib.live(); let mem0 = 0;
const iters = 20000;
for (let i = 0; i < iters; i++) {
  if (i === 1000) mem0 = lib.memoryBytes();
  lib.parse(i % 7 === 0 ? errIn : doc);
  if (process.env.VBM_JSON_TEST_LEAK && i % 2) lib.exports.vbm_json_wasm_alloc(64);   // a deliberate leak: this check must then FAIL
}
const live1 = lib.live(), growth = lib.memoryBytes() - mem0;
if (live1 !== live0 || growth > 65536) fail(`leak: ${live1 - live0} live bytes, ${growth} bytes of memory growth over ${iters} parses`);
else console.log(`wasm_test: no leak: live bytes unchanged (${live0}), ${growth} bytes of growth over ${iters} parses`);

if (failures) { console.error(`wasm_test: ${failures} failure(s)`); process.exit(1); }
console.log("wasm_test: ok");
